//! Offline vanilla registry identities for each verified Minecraft target.
//!
//! These catalogs are generated by `sand-build` from verified server reports.
//! They are deliberately independent of the Rust codegen target of the binary:
//! selecting a pack target must also select its content, diagnostics and IDE
//! suggestions. Loading this module never downloads or reads a host cache.

use std::collections::BTreeMap;
use std::sync::OnceLock;

type Variants = BTreeMap<String, String>;
type Catalog = BTreeMap<String, BTreeMap<String, Variants>>;

fn catalogs() -> &'static Catalog {
    static CATALOG: OnceLock<Catalog> = OnceLock::new();
    CATALOG.get_or_init(|| {
        let value: serde_json::Value = serde_json::from_str(include_str!("vanilla_catalog.json"))
            .expect("generated vanilla catalog is valid JSON");
        assert_eq!(value["format_version"], 1);
        value["targets"]
            .as_object()
            .expect("catalog targets")
            .iter()
            .map(|(version, target)| {
                let registries = serde_json::from_value(target["registries"].clone())
                    .expect("catalog registry entries");
                (version.clone(), registries)
            })
            .collect()
    })
}

/// Exact Minecraft versions for which offline vanilla content is available.
///
/// No neighboring release is substituted for an absent version. Frontends can
/// use this list to advertise content support independently of binary codegen.
pub fn targets() -> impl Iterator<Item = &'static str> {
    catalogs().keys().map(String::as_str)
}

/// Vanilla variant names and resource identities for one target and registry.
///
/// `registry` is a namespaced registry identity such as `minecraft:item`.
/// `latest` resolves through Sand's verified anchor; a trailing zero patch is
/// normalized, so `26.2.0` and `26.2` select the same data. Unknown targets or
/// registries return `None`, never a guessed nearest version.
pub fn variants(target: &str, registry: &str) -> Option<&'static Variants> {
    let target = if target == "latest" {
        crate::LATEST_KNOWN
    } else {
        target
    };
    let versions = catalogs();
    let version = versions
        .get(target)
        .or_else(|| target.strip_suffix(".0").and_then(|key| versions.get(key)))?;
    version.get(registry)
}

/// Whether a vanilla identity exists in an exact target's registry.
///
/// `None` means the catalog or registry is unavailable; `Some(false)` means the
/// catalog was found and the identity is absent. Custom namespaces should be
/// handled explicitly by the caller's interoperability policy.
pub fn contains(target: &str, registry: &str, id: &str) -> Option<bool> {
    Some(
        variants(target, registry)?
            .values()
            .any(|value| value == id),
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn catalogs_preserve_target_boundaries_and_exact_aliases() {
        assert_eq!(
            contains("26.2", "minecraft:item", "minecraft:black_concrete_slab"),
            Some(false)
        );
        assert_eq!(
            contains("26.3", "minecraft:item", "minecraft:black_concrete_slab"),
            Some(true)
        );
        assert_eq!(
            contains("26.2.0", "minecraft:item", "minecraft:bread"),
            Some(true)
        );
        assert_eq!(contains("27.0", "minecraft:item", "minecraft:bread"), None);
        for version in targets() {
            for registry in [
                "item",
                "block",
                "entity_type",
                "sound_event",
                "particle_type",
                "attribute",
                "mob_effect",
                "potion",
                "worldgen/biome",
                "enchantment",
            ] {
                assert!(
                    !variants(version, &format!("minecraft:{registry}"))
                        .unwrap()
                        .is_empty(),
                    "{version}/{registry}"
                );
            }
        }
    }
}
